import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Line, Bar, Pie, Doughnut } from 'react-chartjs-2'; // Doughnut added for Gauge
import { jsPDF } from "jspdf"; // ✅ Idhu dhaan correct-ana standard import
import html2canvas from 'html2canvas';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, 
  BarElement, ArcElement, Title, Tooltip, Legend, Filler
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Title, Tooltip, Legend, Filler);

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);
  const [authData, setAuthData] = useState({ username: '', password: '' });

  // 💰 VIRTUAL WALLET, HOLDINGS & LIVE PRICE STATES
  const [wallet, setWallet] = useState(100000); 
  const [holdings, setHoldings] = useState({}); 
  const [livePrice, setLivePrice] = useState(0); 
  const [priceHistory, setPriceHistory] = useState([]); 
  const prevDecisionRef = useRef(null); // Upgrade 3: AI Signal tracking

  const stockList = [
    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  // 🟢 LIVE SIMULATION + AUTO-SELL LOGIC
  useEffect(() => {
    if (isLoggedIn && data) {
      setLivePrice(data.current_price);
      setPriceHistory([data.current_price]);

      const interval = setInterval(() => {
        setLivePrice(prev => {
          const fluctuation = (Math.random() - 0.5) * 2.5; 
          const newPrice = prev + fluctuation;
          
          Object.keys(holdings).forEach(symbol => {
            if (holdings[symbol].qty > 0) {
              const buyPrice = holdings[symbol].avgPrice;
              const targetPrice = buyPrice * 1.005; 
              const stopLossPrice = buyPrice * 0.995; 

              if (newPrice >= targetPrice) {
                executeAutoExecution(symbol, newPrice, "🚀 TARGET REACHED! Profit Captured.");
              } else if (newPrice <= stopLossPrice) {
                executeAutoExecution(symbol, newPrice, "🛡️ STOP LOSS TRIGGERED! Capital Saved.");
              }
            }
          });

          setPriceHistory(history => [...history, newPrice].slice(-20));
          return newPrice;
        });
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [data, isLoggedIn, holdings]);

  useEffect(() => {
    if (data && data.decision === "BUY" && prevDecisionRef.current !== "BUY") {
      alert(`🔔 AI SIGNAL ALERT: High probability BUY signal detected for ${data.symbol}!`);
    }
    prevDecisionRef.current = data?.decision;
  }, [data]);

  const executeAutoExecution = (symbol, price, reason) => {
    const qty = holdings[symbol].qty;
    setWallet(w => w + (price * qty));
    setHoldings(h => {
      const updated = { ...h };
      delete updated[symbol]; 
      return updated;
    });
    alert(`🤖 AUTO-EXECUTION: ${reason}\nSold at: ₹${price.toFixed(2)}`);
  };

  const calculatePnL = () => {
    let totalPnL = 0;
    Object.keys(holdings).forEach(symbol => {
      if (data && data.symbol === symbol) {
        totalPnL += (livePrice - holdings[symbol].avgPrice) * holdings[symbol].qty;
      }
    });
    return totalPnL;
  };

  const executeTrade = (action) => {
    if (!data) return;
    const price = livePrice;
    const symbol = data.symbol;

    if (action === "BUY") {
      if (wallet >= price) {
        setWallet(prev => prev - price);
        setHoldings(prev => {
          const current = prev[symbol] || { qty: 0, avgPrice: 0 };
          const newQty = current.qty + 1;
          const newAvg = ((current.avgPrice * current.qty) + price) / newQty;
          return { ...prev, [symbol]: { qty: newQty, avgPrice: newAvg } };
        });
        alert(`AI Trade Success: Bought 1 share of ${symbol}`);
      } else { alert("Insufficient balance!"); }
    } else if (action === "SELL") {
      if (holdings[symbol] && holdings[symbol].qty > 0) {
        setWallet(prev => prev + (price * holdings[symbol].qty));
        setHoldings(prev => {
          const updated = { ...prev };
          delete updated[symbol];
          return updated;
        });
        alert(`AI Trade Success: Sold holdings of ${symbol}`);
      } else { alert("No shares to sell!"); }
    }
  };

  const handleAuth = async () => {
    if(authData.username && authData.password) setIsLoggedIn(true);
    else alert("Please enter credentials");
  };

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        const result = Array.isArray(res.data) ? res.data[0] : res.data;
        setData(result);
        setLoading(false);
      }).catch(err => { console.error(err); setLoading(false); });
  };

  useEffect(() => { if (isLoggedIn) fetchData(selectedStock); }, [selectedStock, isLoggedIn]);

  const liveGraphData = {
    labels: priceHistory.map((_, i) => `${i}s`),
    datasets: [{ label: `Live ${data?.symbol} Trend (₹)`, data: priceHistory, borderColor: '#4facfe', backgroundColor: 'rgba(79, 172, 254, 0.1)', fill: true, tension: 0.4, pointRadius: 0 }]
  };

  const pieData = {
    labels: ['Equities', 'Hedge', 'Cash'],
    datasets: [{ data: data?.regime === "STRESS" ? [40, 50, 10] : [70, 10, 20], backgroundColor: ['#4facfe', '#f85149', '#cbd5e1'], borderWidth: 0 }]
  };

  const downloadReport = () => {
    const input = document.getElementById('report-area');
    html2canvas(input).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      pdf.addImage(imgData, 'PNG', 0, 0, 210, (canvas.height * 210) / canvas.width);
      pdf.save(`QuantShield_Report_${selectedStock}.pdf`);
    });
  };

  if (!isLoggedIn) {
    return (
      <div style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`, backgroundSize: 'cover', backgroundPosition: 'center', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" }}>
        <div style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', borderRadius: '30px', width: '900px', display: 'flex', gap: '40px', color: 'white', border: '1px solid rgba(255,255,255,0.2)' }}>
          <div style={{ flex: 1 }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', color: '#00f2fe' }}>QuantShield</h1>
             <p style={{ fontSize: '18px', opacity: 0.8 }}>Advanced AI-Driven Portfolio Optimization and Risk Forecasting System</p>
          </div>
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px' }}>
            <h2 style={{ marginBottom: '20px' }}>LOGIN</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', color: '#002f35', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>SIGN IN</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      
      {/* 🟢 SIDEBAR ALIGNMENT FIXED */}
      <div style={{ 
        width: '280px', 
        background: '#1e293b', 
        padding: '40px 20px', 
        position: 'fixed', 
        height: '100vh', 
        zIndex: 10,
        display: 'flex',
        flexDirection: 'column',
        gap: '10px',
        borderRight: '1px solid rgba(255,255,255,0.05)'
      }}>
        <h2 style={{ 
          color: '#00f2fe', 
          fontWeight: '900', 
          marginBottom: '40px', 
          fontSize: '24px', 
          paddingLeft: '15px' 
        }}>🛡️ QuantShield</h2>
        
        {["Dashboard", "Analytics", "Stocks", "Settings"].map(tab => (
          <div 
            key={tab} 
            onClick={() => setActiveTab(tab)} 
            style={{ 
              background: activeTab === tab ? 'rgba(0, 242, 254, 0.15)' : 'transparent', 
              color: activeTab === tab ? '#00f2fe' : '#94a3b8', 
              padding: '16px 20px', 
              borderRadius: '12px', 
              fontWeight: '600', 
              cursor: 'pointer', 
              transition: '0.3s all ease',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              borderLeft: activeTab === tab ? '4px solid #00f2fe' : '4px solid transparent'
            }}
          >
             {tab === "Dashboard" ? "📊 " : tab === "Analytics" ? "📈 " : tab === "Stocks" ? "💹 " : "⚙️ "}
             {tab}
          </div>
        ))}

        <div 
          style={{ 
            position: 'absolute', 
            bottom: '30px', 
            left: '20px', 
            right: '20px',
            color: '#f85149', 
            fontWeight: 'bold', 
            cursor: 'pointer',
            padding: '15px',
            borderRadius: '10px',
            textAlign: 'center',
            background: 'rgba(248, 81, 73, 0.05)',
            transition: '0.3s'
          }} 
          onClick={() => setIsLoggedIn(false)}
        >
          🔒 Logout
        </div>
      </div>

      {/* Indha Sidebar-ku apparam unga rest of the code inga start aaganum... */}
      <div style={{ flex: 1, padding: '40px', marginLeft: '280px' }}>
          {/* Dashboard contents inga irukkum */}
      </div>

    </div> // Indha div closing return statement-oda final closing
  );

        <div id="report-area">
          {activeTab === "Dashboard" && data && (
            <>
              {/* 📊 CORE STATUS CARDS */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' }}>
                <MiniCard title="TOTAL UNREALIZED P&L" value={`₹${calculatePnL().toFixed(2)}`} color={calculatePnL() >= 0 ? "#22c55e" : "#ef4444"} />
                <MiniCard title="LIVE TICKER PRICE" value={`₹${livePrice.toFixed(2)}`} color="#4facfe" />
                <MiniCard title="AI DECISION VERDICT" value={data.decision} color={data.decision === "BUY" ? "#22c55e" : "#f59e0b"} />
              </div>

              {/* 🟢 ALIGNED GAUGE & TRADE CONTROL */}
              <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 2fr', gap: '25px', marginBottom: '30px', alignItems: 'stretch' }}>
                 <div style={{ background: 'white', padding: '25px', borderRadius: '24px', textAlign: 'center', border: '1px solid #f1f5f9', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                    <small style={{ color: '#64748b', fontWeight: 'bold' }}>AI SENTIMENT GAUGE</small>
                    <div style={{ height: '140px', marginTop: '10px', display: 'flex', justifyContent: 'center', position: 'relative' }}>
                       <Doughnut data={{ labels: ['Bullish', 'Neutral'], datasets: [{ data: [parseFloat(data.bsi_score), 100-parseFloat(data.bsi_score)], backgroundColor: ['#00f2fe', '#f1f5f9'], circumference: 180, rotation: 270 }] }} options={{ cutout: '80%', plugins: { legend: { display: false } } }} />
                       <div style={{ position: 'absolute', bottom: '15px', fontSize: '20px', fontWeight: '900', color: '#4facfe' }}>{data.bsi_score}</div>
                    </div>
                 </div>

                 <div style={{ background: 'white', padding: '30px', borderRadius: '24px', border: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <h3 style={{ margin: 0, fontSize: '20px' }}>Trade {data.symbol}</h3>
                      <p style={{ color: '#64748b', fontSize: '13px', marginTop: '5px' }}>Avg Price: <b>₹{holdings[data.symbol]?.avgPrice.toFixed(2) || '0.00'}</b> | Shares: <b>{holdings[data.symbol]?.qty || 0}</b></p>
                    </div>
                    <div style={{ display: 'flex', gap: '15px' }}>
                      <button onClick={() => executeTrade("BUY")} style={{ padding: '15px 35px', background: '#166534', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>BUY</button>
                      <button onClick={() => executeTrade("SELL")} style={{ padding: '15px 35px', background: '#991b1b', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>SELL</button>
                    </div>
                 </div>
              </div>

              {/* 📈 MOMENTUM & HEATMAP ALIGNMENT */}
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '30px', alignItems: 'stretch' }}>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', display: 'flex', flexDirection: 'column' }}>
                  <h3 style={{ marginBottom: '15px' }}>Momentum Velocity (1s Sync)</h3>
                  <div style={{ flex: 1, minHeight: '300px' }}><Line data={liveGraphData} options={{ maintainAspectRatio: false, animation: { duration: 0 }, scales: { x: { display: false } } }} /></div>
                </div>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', textAlign: 'center', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                  <h3 style={{ marginBottom: '15px' }}>Allocation Heatmap</h3>
                  <div style={{ height: '220px', display: 'flex', justifyContent: 'center' }}><Pie data={pieData} /></div>
                  <p style={{ marginTop: '15px', fontWeight: 'bold', color: '#64748b' }}>Market: {data.regime}</p>
                </div>
              </div>
            </>
          )}

          {/* 📈 ANALYTICS TAB (Backtesting Log) */}
          {activeTab === "Analytics" && (
            <div style={{ animation: 'fadeIn 0.5s ease-in-out' }}>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' }}>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
                  <small style={{ color: '#64748b' }}>AI ACCURACY</small>
                  <div style={{ fontSize: '28px', fontWeight: '900', color: '#4facfe' }}>94.2%</div>
                </div>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
                  <small style={{ color: '#64748b' }}>TOTAL TRADES</small>
                  <div style={{ fontSize: '28px', fontWeight: '900', color: '#166534' }}>128</div>
                </div>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
                  <small style={{ color: '#64748b' }}>SUCCESS RATIO</small>
                  <div style={{ fontSize: '28px', fontWeight: '900', color: '#3fb950' }}>82%</div>
                </div>
              </div>

              <div style={{ background: 'white', padding: '30px', borderRadius: '24px', border: '1px solid #f1f5f9' }}>
                <h3>📋 AI Backtesting Log</h3>
                <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '15px' }}>
                  <thead><tr style={{ textAlign: 'left', color: '#64748b', borderBottom: '2px solid #f1f5f9' }}><th>Timestamp</th><th>Asset</th><th>Signal</th><th>Result</th><th>P&L</th></tr></thead>
                  <tbody style={{ fontSize: '14px' }}>
                    <tr style={{ borderBottom: '1px solid #f8fafc' }}><td style={{ padding: '12px' }}>16 Mar 14:20</td><td>TCS.NS</td><td style={{ color: '#22c55e' }}>BUY</td><td>TARGET HIT</td><td>+ ₹19.40</td></tr>
                    <tr style={{ borderBottom: '1px solid #f8fafc' }}><td style={{ padding: '12px' }}>16 Mar 11:45</td><td>SBIN.NS</td><td style={{ color: '#22c55e' }}>BUY</td><td>STOP LOSS</td><td style={{ color: '#ef4444' }}>- ₹5.20</td></tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === "Stocks" && (
            <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
              <h3>💹 Live Asset Watchlist</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
                <thead><tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b' }}><th style={{ padding: '15px', textAlign: 'left' }}>Stock</th><th style={{ textAlign: 'left' }}>Price</th><th style={{ textAlign: 'left' }}>Action</th></tr></thead>
                <tbody>{stockList.map(s => (<tr key={s.symbol} style={{ borderBottom: '1px solid #f1f5f9' }}><td style={{ padding: '15px', fontWeight: 'bold' }}>{s.name}</td><td>₹{s.symbol === "HDFCBANK.NS" ? "816.70" : "1,142.50"}</td><td><button onClick={() => { setSelectedStock(s.symbol); setActiveTab("Dashboard"); }} style={{ background: '#4facfe', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Analyze</button></td></tr>))}</tbody>
              </table>
            </div>
          )}

           {activeTab === "Settings" && (

            <div style={{ animation: 'fadeIn 0.5s ease-in-out' }}>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '30px' }}>

                <div style={{ background: 'white', padding: '40px', borderRadius: '24px', textAlign: 'center', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>

                  <div style={{ width: '100px', height: '100px', borderRadius: '50%', background: 'linear-gradient(45deg, #4facfe, #00f2fe)', margin: '0 auto 20px', color: 'white', fontSize: '40px', display: 'flex', justifyContent: 'center', alignItems: 'center', fontWeight: 'bold' }}>S</div>

                  <h3 style={{ margin: '10px 0 5px 0' }}>Suresh M</h3>

                  <p style={{ color: '#64748b', fontSize: '14px' }}>QuantShield Pro Investor</p>

                  <div style={{ marginTop: '20px', padding: '10px', background: '#f0fdf4', color: '#166534', borderRadius: '10px', fontSize: '12px', fontWeight: 'bold' }}>VERIFIED ✅</div>

                </div>

                <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>

                  <h3 style={{ marginBottom: '25px' }}>System Preferences</h3>

                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '15px 0', borderBottom: '1px solid #f1f5f9' }}>

                    <div><b>Ghost Hedge Protection</b><div style={{ fontSize: '12px', color: '#64748b' }}>Active risk management</div></div>

                    <div style={{ color: '#22c55e', fontWeight: 'bold' }}>ENABLED</div>

                  </div>

                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '15px 0' }}>

                    <div><b>AI Prediction Accuracy</b><div style={{ fontSize: '12px', color: '#64748b' }}>Backtested score</div></div>

                    <div style={{ color: '#4facfe', fontWeight: 'bold' }}>94.2%</div>

                  </div>

                  <button style={{ marginTop: '30px', width: '100%', padding: '15px', background: '#f4f7fe', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>Edit Security</button>

                </div>

              </div>

            </div>

          )}
        </div>
      
    
  
}

function MiniCard({ title, value, color }) {
  return (
    <div style={{ background: 'white', padding: '25px', borderRadius: '20px', borderLeft: `6px solid ${color}`, boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
      <div style={{ color: '#64748b', fontSize: '11px', fontWeight: 'bold', marginBottom: '5px' }}>{title}</div>
      <div style={{ fontSize: '24px', fontWeight: '800' }}>{value}</div>
    </div>
  );
}

export default App;
